#include <stdio.h>
typedef struct person {
    int age;            // 나이를 나타내는 정수값
    int height;         // 키(cm) · 강의는 float
} person;
int main(void)
{
    person a = { 20, 170 }, b;
    b = a;                  // 가능
    a.age = a.age + 1;      // a만 바꾸면?
    if( a.age > b.age )     // 필드를 골라 비교
        printf("a가 b보다 나이가 많음");
    return 0;
}

#include <stdio.h>
typedef struct person {
    int age;            // 나이를 나타내는 정수값
    int height;         // 키(cm) · 강의는 float
} person;
int main(void)
{
    person a, b;
    b = a;                  // 가능
    return 0;
}

#include <stddef.h>
typedef struct ListNode {
    int data;               // 강의는 char data[10]
    struct ListNode *link;
} ListNode;
int main(void)
{
    ListNode n2 = { 170, NULL };
    ListNode n1 = { 20, &n2 };
    ListNode c;
    c = n1;                 // 필드별 복사
    c.data = c.data + 1;    // c만 바뀜
    c.link->data = 0;       // n2를 바꿈
    int seen = n1.link->data;   // n1에서 보면?
    return 0;
}

